#!/usr/bin/env bash
set -Eeuo pipefail
umask 0077

TARGET="/tmp/12_zcr17_provenance_fix_and_gate_v39.sh"
EXPECTED_SHA256="6c11cc08e86c19e859a439b32603b4f53cbca0fe837d5420e073aa289bc6d22c"
EXPECTED_GIT_BLOB="f046f1be992d60c10f768e419462c7e5d2917881"

base64 -d <<'PAYLOAD' | gzip -d > "$TARGET"

PAYLOAD

[[ "$(sha256sum "$TARGET" | awk '{print $1}')" == "$EXPECTED_SHA256" ]] || {
  echo "ERRO: payload V3.9 SHA256 divergente" >&2
  exit 1
}
[[ "$(git hash-object "$TARGET")" == "$EXPECTED_GIT_BLOB" ]] || {
  echo "ERRO: payload V3.9 Git blob divergente" >&2
  exit 1
}
bash -n "$TARGET"
chmod 700 "$TARGET"

echo "ONÇA ZCR17 PROVENANCE FIX + GATE V3.9: ÍNTEGRO"
exec bash "$TARGET"
